#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> left_sums, right_sums;
    int half = n / 2;

    function<void(int, int)> calc_left = [&](int i, int total) {
        if (i == half) {
            left_sums.push_back(total);
        } else {
            calc_left(i + 1, (total + a[i]) % m);
            calc_left(i + 1, total);
        }
    };

    function<void(int, int)> calc_right = [&](int i, int total) {
        if (i == n) {
            right_sums.push_back(total);
        } else {
            calc_right(i + 1, (total + a[i]) % m);
            calc_right(i + 1, total);
        }
    };

    calc_left(0, 0);
    calc_right(half, 0);

    set<int> unique_left(left_sums.begin(), left_sums.end());
    vector<int> unique_left_vec(unique_left.begin(), unique_left.end());

    int max_total = 0;
    for (int val : right_sums) {
        int target = m - val;
        auto it = std::lower_bound(unique_left_vec.begin(), unique_left_vec.end(), target);
        if (it != unique_left_vec.begin()) {
            --it;
            int candidate = *it + val;
            if (candidate > max_total) {
                max_total = candidate;
            }
        }
    }

    cout << max_total << "\n";

    return 0;
}
